   681  int
   682  cdf_read_dir(const cdf_info_t *info, const cdf_header_t *h,
   683      const cdf_sat_t *sat, cdf_dir_t *dir)
   684  {
   685          size_t i, j;
   686          size_t ss = CDF_SEC_SIZE(h), ns, nd;
   687          char *buf;
   688          cdf_secid_t sid = h->h_secid_first_directory;
   689
   690          ns = cdf_count_chain(sat, sid, ss);
   691          if (ns == CAST(size_t, -1))
   692                  return -1;
   693
   694          nd = ss / CDF_DIRECTORY_SIZE;
   695
   696          dir->dir_len = ns * nd;
   697          dir->dir_tab = CAST(cdf_directory_t *,
   698              CDF_CALLOC(dir->dir_len, sizeof(dir->dir_tab[0])));
   699          if (dir->dir_tab == NULL)
   700                  return -1;
   701
   702          if ((buf = CAST(char *, CDF_MALLOC(ss))) == NULL) {
   703                  free(dir->dir_tab);
   704                  return -1;
   705          }
   706
   707          for (j = i = 0; i < ns; i++, j++) {
   708                  if (j >= CDF_LOOP_LIMIT) {
   709                          DPRINTF(("Read dir loop limit"));
   710                          goto out;
   711                  }
   712                  if (cdf_read_sector(info, buf, 0, ss, h, sid) !=
   713                      CAST(ssize_t, ss)) {
   714                          DPRINTF(("Reading directory sector %d", sid));
   715                          goto out;
   716                  }
   717                  for (j = 0; j < nd; j++) {
   718                          cdf_unpack_dir(&dir->dir_tab[i * nd + j],
   719                              &buf[j * CDF_DIRECTORY_SIZE]);
   720                  }
   721                  sid = CDF_TOLE4(CAST(uint32_t, sat->sat_tab[sid]));
   722          }
   723          if (NEED_SWAP)
   724                  for (i = 0; i < dir->dir_len; i++)
   725                          cdf_swap_dir(&dir->dir_tab[i]);
   726          free(buf);
   727          return 0;
   728  out:
   729          free(dir->dir_tab);
   730          free(buf);
   731          errno = EFTYPE;
   732          return -1;
   733  }
