   750          if (ssat->sat_tab == NULL)
   751                  goto out1;
   752
   753          for (j = i = 0; sid >= 0; i++, j++) {
   754                  if (j >= CDF_LOOP_LIMIT) {
   755                          DPRINTF(("Read short sat sector loop limit"));
   756                          goto out;
   757                  }
   758                  if (i >= ssat->sat_len) {
   759                          DPRINTF(("Out of bounds reading short sector chain "
   760                              "%" SIZE_T_FORMAT "u > %" SIZE_T_FORMAT "u\n", i,
   761                              ssat->sat_len));
   762                          goto out;
   763                  }
   764                  if (cdf_read_sector(info, ssat->sat_tab, i * ss, ss, h, sid) !=
   765                      CAST(ssize_t, ss)) {
   766                          DPRINTF(("Reading short sat sector %d", sid));
   767                          goto out1;
   768                  }
   769                  sid = CDF_TOLE4(CAST(uint32_t, sat->sat_tab[sid]));
   770          }
   771          return 0;
   772  out:
   773          errno = EFTYPE;
   774  out1:
   775          free(ssat->sat_tab);
   776          return -1;
