   452  int
   453  cdf_read_sat(const cdf_info_t *info, cdf_header_t *h, cdf_sat_t *sat)
   454  {
   455          size_t i, j, k;
   456          size_t ss = CDF_SEC_SIZE(h);
   457          cdf_secid_t *msa, mid, sec;
   458          size_t nsatpersec = (ss / sizeof(mid)) - 1;
   459
   460          for (i = 0; i < __arraycount(h->h_master_sat); i++)
   461                  if (h->h_master_sat[i] == CDF_SECID_FREE)
   462                          break;
   463
   464  #define CDF_SEC_LIMIT (UINT32_MAX / (64 * ss))
   465          if ((nsatpersec > 0 &&
   466              h->h_num_sectors_in_master_sat > CDF_SEC_LIMIT / nsatpersec) ||
   467              i > CDF_SEC_LIMIT) {
   468                  DPRINTF(("Number of sectors in master SAT too big %u %"
   469                      SIZE_T_FORMAT "u\n", h->h_num_sectors_in_master_sat, i));
   470                  errno = EFTYPE;
   471                  return -1;
   472          }
   473
   474          sat->sat_len = h->h_num_sectors_in_master_sat * nsatpersec + i;
   475          DPRINTF(("sat_len = %" SIZE_T_FORMAT "u ss = %" SIZE_T_FORMAT "u\n",
   476              sat->sat_len, ss));
   477          if ((sat->sat_tab = CAST(cdf_secid_t *, CDF_CALLOC(sat->sat_len, ss)))
   478              == NULL)
   479                  return -1;
   480
   481          for (i = 0; i < __arraycount(h->h_master_sat); i++) {
   482                  if (h->h_master_sat[i] < 0)
   483                          break;
   484                  if (cdf_read_sector(info, sat->sat_tab, ss * i, ss, h,
   485                      h->h_master_sat[i]) != CAST(ssize_t, ss)) {
   486                          DPRINTF(("Reading sector %d", h->h_master_sat[i]));
   487                          goto out1;
   488                  }
   489          }
   490
   491          if ((msa = CAST(cdf_secid_t *, CDF_CALLOC(1, ss))) == NULL)
   492                  goto out1;
   493
   494          mid = h->h_secid_first_sector_in_master_sat;
   495          for (j = 0; j < h->h_num_sectors_in_master_sat; j++) {
   496                  if (mid < 0)
   497                          goto out;
   498                  if (j >= CDF_LOOP_LIMIT) {
   499                          DPRINTF(("Reading master sector loop limit"));
   500                          goto out3;
   501                  }
   502                  if (cdf_read_sector(info, msa, 0, ss, h, mid) !=
   503                      CAST(ssize_t, ss)) {
   504                          DPRINTF(("Reading master sector %d", mid));
   505                          goto out2;
   506                  }
   507                  for (k = 0; k < nsatpersec; k++, i++) {
   508                          sec = CDF_TOLE4(CAST(uint32_t, msa[k]));
   509                          if (sec < 0)
   510                                  goto out;
   511                          if (i >= sat->sat_len) {
   512                              DPRINTF(("Out of bounds reading MSA %"
   513                                  SIZE_T_FORMAT "u >= %" SIZE_T_FORMAT "u",
   514                                  i, sat->sat_len));
   515                              goto out3;
   516                          }
   517                          if (cdf_read_sector(info, sat->sat_tab, ss * i, ss, h,
   518                              sec) != CAST(ssize_t, ss)) {
   519                                  DPRINTF(("Reading sector %d",
   520                                      CDF_TOLE4(msa[k])));
   521                                  goto out2;
   522                          }
   523                  }
   524                  mid = CDF_TOLE4(CAST(uint32_t, msa[nsatpersec]));
   525          }
   526  out:
   527          sat->sat_len = i;
   528          free(msa);
   529          return 0;
   530  out3:
   531          errno = EFTYPE;
   532  out2:
   533          free(msa);
   534  out1:
   535          free(sat->sat_tab);

